// Define the Result type as a discriminated union
type Result<T, E> =
  | { success: true; data: T }
  | { success: false; error: E };

// Example API function (simulates fetching data)
function fetchData<T, E>(shouldSucceed: boolean): Result<T, E> {
  if (shouldSucceed) {
    return { success: true, data: "Data fetched successfully!" as T };
  } else {
    return { success: false, error: "Failed to fetch data." as E };
  }
}

// Safely read the result using a type guard function
function processResult<T, E>(result: Result<T, E>): T | null {
  if (result.success) {
    return result.data; // TypeScript knows 'data' exists because of the 'success' check
  } else {
    console.error(result.error);
    return null; // Or handle the error in a more sophisticated way
  }
}

// Usage
const successResult = fetchData<string, Error>(true);
const failureResult = fetchData<string, Error>(false);

const data = processResult(successResult);
if (data) {
  console.log("Data:", data);
}

const errorData = processResult(failureResult);
if (errorData === null) {
  console.log("Operation failed.");
}
```

